//! 📦️ An original-bound reader moves into fixed stable owned storage before a borrowed semantic continuation starts.
use super::*;
use super::super::graph::LayoutGraphRead;
use std::mem::size_of;
/// 🛡️ A concrete reader owns its original leases and paid descriptor storage; closure starts only after all graph borrows retire.
pub trait OwnedLayoutGraphRead:Send+Sync{fn graph(&self)->&dyn LayoutGraphRead;fn begin_close(&mut self);fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>;fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>;fn terminal_is_empty(&self)->bool;}
#[derive(Default)]pub struct OwnedLayoutGraphValidation{reader:Option<Box<dyn OwnedLayoutGraphRead>>,reader_bytes:usize,reader_closing:bool,program:Option<Program>,program_bytes:usize,index:index::Index,started:bool,done:bool,closing:bool,error:Option<&'static str>}
impl OwnedLayoutGraphValidation{
 const META:usize=256;
 fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"Owned Layout graph validation frontier is invalid")}
 fn nested(d:RetirementDemand)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:d.copy_bytes.checked_add(Self::META).ok_or_else(Self::invalid)?,depth:d.depth.checked_add(1).ok_or_else(Self::invalid)?,..d})}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(Self::META),maximum_depth:g.maximum_depth.saturating_sub(1),..g}}
 fn paid(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes=p.copied_bytes.saturating_add(Self::META);p}
 fn error(error:ValueError)->ValueError{let p=Self::paid(error.retained_progress());error.with_retained_progress(p)}
 pub fn new()->Self{Default::default()}
 pub fn reader_birth_demand<G:OwnedLayoutGraphRead+'static>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<G>()*2+Self::META,capacity_bytes:size_of::<G>(),depth:1,..Default::default()}}
 pub fn start<G:OwnedLayoutGraphRead+'static>(&mut self,reader:G,g:RetainedCloneGrant)->Result<RetainedCloneProgress,(ValueError,G)>{let d=Self::reader_birth_demand::<G>();if self.reader.is_some()||self.closing||!retained_clone_grant_admits(g,d){return Err((Self::invalid(),reader))}self.reader=Some(Box::new(reader));self.reader_bytes=size_of::<G>();Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()})}
 fn future_bytes(&self)->Result<usize,ValueError>{Ok(size_of_val(&program::check_document(self.reader.as_ref().ok_or_else(Self::invalid)?.graph(),self.index.slots())))}
 pub fn demand(&self,_body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.reader.is_none(){return Err(Self::invalid())}if self.done{return Ok(Default::default())}if !self.index.done(){return Self::nested(self.index.demand()?)}if !self.started{let bytes=self.future_bytes()?;return Ok(RetirementDemand{copy_bytes:bytes*2+Self::META,capacity_bytes:bytes,depth:1,..Default::default()})}Ok(RetirementDemand{copy_bytes:self.program_bytes.checked_mul(2).and_then(|n|n.checked_add(1024+Self::META)).ok_or_else(Self::invalid)?,depth:1,..Default::default()})}
 pub fn advance(&mut self,body:usize,g:RetainedCloneGrant)->Result<ValidationAdvance,ValueError>{let d=self.demand(body)?;let mut out=ValidationAdvance{progress:Default::default(),done:self.done,error:self.error};if self.done||!retained_clone_grant_admits(g,d){return Ok(out)}if !self.index.done(){out.progress=Self::paid(self.index.advance(self.reader.as_ref().ok_or_else(Self::invalid)?.graph(),Self::child(g)).map_err(Self::error)?);if let Some(error)=self.index.error(){self.error=Some(error);self.done=true;out.done=true;out.error=Some(error)}return Ok(out)}out.progress=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if !self.started{self.program_bytes=self.future_bytes()?;let graph=self.reader.as_ref().ok_or_else(Self::invalid)?.graph()as*const dyn LayoutGraphRead;let loan:&'static dyn LayoutGraphRead=unsafe{&*graph};let slots:index::Slots<'static>=unsafe{std::mem::transmute(self.index.slots())};self.program=Some(Box::pin(program::check_document(loan,slots)));self.started=true;out.progress.retained_capacity_bytes=self.program_bytes;return Ok(out)}let mut cx=Context::from_waker(Waker::noop());if let Poll::Ready(result)=self.program.as_mut().ok_or_else(Self::invalid)?.as_mut().poll(&mut cx){self.done=true;self.error=result.err();out.done=true;out.error=self.error}Ok(out)}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.program.is_some(){return Ok(RetirementDemand{copy_bytes:self.program_bytes*2+Self::META,release_bytes:self.program_bytes,depth:1,..Default::default()})}if !self.index.terminal_is_empty(){return Self::nested(self.index.close_demand())}if let Some(reader)=&self.reader{if !self.reader_closing{return Ok(RetirementDemand{copy_bytes:Self::META,depth:1,..Default::default()})}if !reader.terminal_is_empty(){return Self::nested(reader.close_demand(body.saturating_sub(Self::META))?)}return Ok(RetirementDemand{copy_bytes:self.reader_bytes*2+Self::META,release_bytes:self.reader_bytes,depth:1,..Default::default()})}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(Self::invalid())}let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.program.is_some(){self.program=None;self.program_bytes=0;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))}if !self.index.terminal_is_empty(){return self.index.close_step(Self::child(g)).map(|p|RetainedCloneStep::Progress(Self::paid(p))).map_err(Self::error)}let reader=self.reader.as_mut().ok_or_else(Self::invalid)?;if !self.reader_closing{reader.begin_close();self.reader_closing=true;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if !reader.terminal_is_empty(){return reader.close_step(Self::child(g)).map(|p|RetainedCloneStep::Progress(Self::paid(p.progress()))).map_err(Self::error)}self.reader=None;self.reader_bytes=0;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()}))}
 pub fn terminal_is_empty(&self)->bool{self.reader.is_none()&&self.program.is_none()&&self.program_bytes==0&&self.index.terminal_is_empty()}
}
impl Drop for OwnedLayoutGraphValidation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Owned graph reader and continuation require original-funded close")}}
